import type { Word, SentenceItem } from "./schemas";

/**
 * All-parts seed bundled into the app for offline/mock builds.
 * Generated by `scripts/gen-seed.mjs` from database/seeds/parts/*.json.
 * Loaded via require() so tsc does not infer the large JSON literal type.
 * Empty array if the file hasn't been generated yet (build still works).
 */
let seedWords: Word[] = [];
try {
  seedWords = require("../../assets/seed/words.json") as Word[];
} catch {
  seedWords = [];
}

let seedSentences: SentenceItem[] = [];
try {
  seedSentences = require("../../assets/seed/sentences.json") as SentenceItem[];
} catch {
  seedSentences = [];
}

export { seedWords, seedSentences };
